    INSERT INTO job_categories (category_id, category_name, description) VALUES
        (20001, 'Web Development', 'Dự án web development: giao diện responsive, phân quyền quản trị và kiểm thử luồng đặt hàng.'),
        (20002, 'Mobile Applications', 'Dự án mobile applications: đăng nhập, thông báo trạng thái, kiểm thử trên Android và iOS.'),
        (20003, 'Data Engineering', 'Dự án data engineering: chống bản ghi trùng, ghi log lỗi và đối soát tổng số bản ghi.'),
        (20004, 'Business Intelligence', 'Dự án business intelligence: chỉ số có công thức rõ ràng, bộ lọc theo kỳ và số liệu khớp nguồn.'),
        (20005, 'Product Design', 'Dự án product design: prototype có tương tác, component tái sử dụng và bố cục mobile.'),
        (20006, 'Quality Assurance', 'Dự án quality assurance: test có thể chạy lại, báo cáo lỗi tái hiện được và bao phủ luồng chính.'),
        (20007, 'Cloud Engineering', 'Dự án cloud engineering: tách môi trường, có health check, log tập trung và hướng dẫn rollback.'),
        (20008, 'Technical Writing', 'Dự án technical writing: thuật ngữ thống nhất, ví dụ kiểm chứng được và mục lục tra cứu rõ ràng.');
    INSERT INTO jobs (job_id, client_id, category_id, title, description, budget_min, budget_max, created_at, deadline) VALUES
        (22001, 20001, 20001, 'Xây dựng cổng đặt hàng cho Mộc Trà Commerce — chi nhánh trung tâm', 'Mộc Trà Commerce cần xây dựng cổng đặt hàng phục vụ chi nhánh trung tâm trong đợt khai trương. Phạm vi gồm: Thiết kế luồng mua hàng và giao diện mẫu; Lập trình danh mục, giỏ hàng và quản lý đơn; Kiểm thử thanh toán và bàn giao website. Công nghệ/kỹ năng ưu tiên: React, TypeScript và Node.js. Tiêu chí nghiệm thu: giao diện responsive, phân quyền quản trị và kiểm thử luồng đặt hàng. Khách hàng cung cấp nội dung và dữ liệu thử; freelancer bàn giao mã nguồn hoặc file thiết kế, hướng dẫn sử dụng và buổi trao đổi nghiệm thu. Ngân sách tính bằng USD; không bao gồm phí dịch vụ bên thứ ba.', 900, 1800, DATE_SUB(CURRENT_DATE, INTERVAL 90 DAY), DATE_ADD(CURRENT_DATE, INTERVAL 90 DAY)),
        (22002, 20002, 20002, 'Phát triển ứng dụng đặt lịch cho Sen Xanh Services — chi nhánh trung tâm', 'Sen Xanh Services cần phát triển ứng dụng đặt lịch phục vụ chi nhánh trung tâm trong đợt khai trương. Phạm vi gồm: Đặc tả màn hình và thiết kế luồng sử dụng; Lập trình ứng dụng và kết nối API; Kiểm thử thiết bị và bàn giao bản cài. Công nghệ/kỹ năng ưu tiên: React Native, TypeScript và REST API. Tiêu chí nghiệm thu: đăng nhập, thông báo trạng thái, kiểm thử trên Android và iOS. Khách hàng cung cấp nội dung và dữ liệu thử; freelancer bàn giao mã nguồn hoặc file thiết kế, hướng dẫn sử dụng và buổi trao đổi nghiệm thu. Ngân sách tính bằng USD; không bao gồm phí dịch vụ bên thứ ba.', 1200, 2400, DATE_SUB(CURRENT_DATE, INTERVAL 90 DAY), DATE_ADD(CURRENT_DATE, INTERVAL 90 DAY)),
        (22003, 20003, 20003, 'Xây dựng pipeline đồng bộ dữ liệu cho Bếp Nhà Logistics — chi nhánh trung tâm', 'Bếp Nhà Logistics cần xây dựng pipeline đồng bộ dữ liệu phục vụ chi nhánh trung tâm trong đợt khai trương. Phạm vi gồm: Khảo sát nguồn và thiết kế mô hình dữ liệu; Xây dựng pipeline ETL và kiểm tra chất lượng; Chạy đối soát và bàn giao lịch đồng bộ. Công nghệ/kỹ năng ưu tiên: Python, SQL và Docker. Tiêu chí nghiệm thu: chống bản ghi trùng, ghi log lỗi và đối soát tổng số bản ghi. Khách hàng cung cấp nội dung và dữ liệu thử; freelancer bàn giao mã nguồn hoặc file thiết kế, hướng dẫn sử dụng và buổi trao đổi nghiệm thu. Ngân sách tính bằng USD; không bao gồm phí dịch vụ bên thứ ba.', 1050, 2100, DATE_SUB(CURRENT_DATE, INTERVAL 90 DAY), DATE_ADD(CURRENT_DATE, INTERVAL 90 DAY)),
        (22004, 20004, 20004, 'Thiết kế dashboard doanh thu cho An Nhiên Foods — chi nhánh trung tâm', 'An Nhiên Foods cần thiết kế dashboard doanh thu phục vụ chi nhánh trung tâm trong đợt khai trương. Phạm vi gồm: Thống nhất chỉ số và chuẩn hóa nguồn dữ liệu; Thiết kế dashboard và bộ lọc phân tích; Đối soát số liệu và hướng dẫn sử dụng. Công nghệ/kỹ năng ưu tiên: SQL, Power BI và mô hình dữ liệu dạng sao. Tiêu chí nghiệm thu: chỉ số có công thức rõ ràng, bộ lọc theo kỳ và số liệu khớp nguồn. Khách hàng cung cấp nội dung và dữ liệu thử; freelancer bàn giao mã nguồn hoặc file thiết kế, hướng dẫn sử dụng và buổi trao đổi nghiệm thu. Ngân sách tính bằng USD; không bao gồm phí dịch vụ bên thứ ba.', 750, 1500, DATE_SUB(CURRENT_DATE, INTERVAL 90 DAY), DATE_ADD(CURRENT_DATE, INTERVAL 90 DAY)),
        (22005, 20005, 20005, 'Thiết kế trải nghiệm cổng học viên cho Hải Đăng Learning — chi nhánh trung tâm', 'Hải Đăng Learning cần thiết kế trải nghiệm cổng học viên phục vụ chi nhánh trung tâm trong đợt khai trương. Phạm vi gồm: Nghiên cứu nhu cầu và phác thảo wireframe; Thiết kế giao diện và prototype tương tác; Kiểm tra usability và bàn giao design system. Công nghệ/kỹ năng ưu tiên: Figma, UX Research và nguyên tắc thiết kế tiếp cận. Tiêu chí nghiệm thu: prototype có tương tác, component tái sử dụng và bố cục mobile. Khách hàng cung cấp nội dung và dữ liệu thử; freelancer bàn giao mã nguồn hoặc file thiết kế, hướng dẫn sử dụng và buổi trao đổi nghiệm thu. Ngân sách tính bằng USD; không bao gồm phí dịch vụ bên thứ ba.', 600, 1200, DATE_SUB(CURRENT_DATE, INTERVAL 90 DAY), DATE_ADD(CURRENT_DATE, INTERVAL 90 DAY)),
        (22006, 20006, 20006, 'Xây dựng bộ kiểm thử hồi quy cho Mây Trắng Solutions — chi nhánh trung tâm', 'Mây Trắng Solutions cần xây dựng bộ kiểm thử hồi quy phục vụ chi nhánh trung tâm trong đợt khai trương. Phạm vi gồm: Lập kế hoạch và thiết kế test cases; Triển khai automation và ghi nhận lỗi; Chạy hồi quy và bàn giao báo cáo chất lượng. Công nghệ/kỹ năng ưu tiên: Selenium, JavaScript và kiểm thử API. Tiêu chí nghiệm thu: test có thể chạy lại, báo cáo lỗi tái hiện được và bao phủ luồng chính. Khách hàng cung cấp nội dung và dữ liệu thử; freelancer bàn giao mã nguồn hoặc file thiết kế, hướng dẫn sử dụng và buổi trao đổi nghiệm thu. Ngân sách tính bằng USD; không bao gồm phí dịch vụ bên thứ ba.', 675, 1350, DATE_SUB(CURRENT_DATE, INTERVAL 90 DAY), DATE_ADD(CURRENT_DATE, INTERVAL 90 DAY)),
        (22007, 20007, 20007, 'Triển khai hạ tầng ứng dụng cho Bình Minh Cloud — chi nhánh trung tâm', 'Bình Minh Cloud cần triển khai hạ tầng ứng dụng phục vụ chi nhánh trung tâm trong đợt khai trương. Phạm vi gồm: Đánh giá kiến trúc và thiết kế môi trường; Cấu hình container và pipeline CI CD; Kiểm tra rollback và bàn giao runbook. Công nghệ/kỹ năng ưu tiên: Docker, Kubernetes và AWS. Tiêu chí nghiệm thu: tách môi trường, có health check, log tập trung và hướng dẫn rollback. Khách hàng cung cấp nội dung và dữ liệu thử; freelancer bàn giao mã nguồn hoặc file thiết kế, hướng dẫn sử dụng và buổi trao đổi nghiệm thu. Ngân sách tính bằng USD; không bao gồm phí dịch vụ bên thứ ba.', 1350, 2700, DATE_SUB(CURRENT_DATE, INTERVAL 90 DAY), DATE_ADD(CURRENT_DATE, INTERVAL 90 DAY)),
