    INSERT INTO proposals (proposal_id, job_id, freelancer_id, proposed_amount, cover_letter, estimated_days, submitted_at) VALUES
        (23001, 22001, 21001, 1800, 'Chào Hoàng Xuân Dũng, tôi là Cao Bảo Giang, lập trình viên web full stack. Với yêu cầu xây dựng cổng đặt hàng, tôi sẽ dùng React, TypeScript và Node.js và chia việc thành ba mốc: Thiết kế luồng mua hàng và giao diện mẫu; Lập trình danh mục, giỏ hàng và quản lý đơn; Kiểm thử thanh toán và bàn giao website. Tôi đề xuất 60 ngày với ngân sách 1800 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí giao diện responsive, phân quyền quản trị và kiểm thử luồng đặt hàng.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (23002, 22001, 21009, 1770, 'Chào Hoàng Xuân Dũng, tôi là Bùi Minh Hân, lập trình viên web full stack. Với yêu cầu xây dựng cổng đặt hàng, tôi sẽ dùng React, TypeScript và Node.js và chia việc thành ba mốc: Thiết kế luồng mua hàng và giao diện mẫu; Lập trình danh mục, giỏ hàng và quản lý đơn; Kiểm thử thanh toán và bàn giao website. Tôi đề xuất 65 ngày với ngân sách 1770 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí giao diện responsive, phân quyền quản trị và kiểm thử luồng đặt hàng.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY)),
        (23003, 22002, 21002, 2400, 'Chào Mai Minh Hân, tôi là Đinh Gia Bình, lập trình viên ứng dụng di động. Với yêu cầu phát triển ứng dụng đặt lịch, tôi sẽ dùng React Native, TypeScript và REST API và chia việc thành ba mốc: Đặc tả màn hình và thiết kế luồng sử dụng; Lập trình ứng dụng và kết nối API; Kiểm thử thiết bị và bàn giao bản cài. Tôi đề xuất 60 ngày với ngân sách 2400 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí đăng nhập, thông báo trạng thái, kiểm thử trên Android và iOS.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
