        (23397, 22199, 21199, 3390, 'Chào Mai Khánh Hà, tôi là Đinh Hoài Tú, kỹ sư devops và đám mây. Với yêu cầu chuẩn hóa cấu hình vận hành, tôi sẽ dùng Docker, Kubernetes và AWS và chia việc thành ba mốc: Đánh giá kiến trúc và thiết kế môi trường; Cấu hình container và pipeline CI CD; Kiểm tra rollback và bàn giao runbook. Tôi đề xuất 60 ngày với ngân sách 3390 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí tách môi trường, có health check, log tập trung và hướng dẫn rollback.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (23398, 22199, 21007, 3360, 'Chào Mai Khánh Hà, tôi là Hồ Bảo Trúc, kỹ sư devops và đám mây. Với yêu cầu chuẩn hóa cấu hình vận hành, tôi sẽ dùng Docker, Kubernetes và AWS và chia việc thành ba mốc: Đánh giá kiến trúc và thiết kế môi trường; Cấu hình container và pipeline CI CD; Kiểm tra rollback và bàn giao runbook. Tôi đề xuất 65 ngày với ngân sách 3360 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí tách môi trường, có health check, log tập trung và hướng dẫn rollback.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY)),
        (23399, 22200, 21200, 1590, 'Chào Ngô Thanh Quân, tôi là Nguyễn Gia Hân, chuyên viên tài liệu kỹ thuật. Với yêu cầu biên tập tài liệu quản trị hệ thống, tôi sẽ dùng tài liệu Markdown, sơ đồ quy trình và kiểm chứng ví dụ API và chia việc thành ba mốc: Khảo sát sản phẩm và xây dựng đề cương; Biên soạn nội dung và ví dụ sử dụng; Rà soát thuật ngữ và bàn giao tài liệu. Tôi đề xuất 60 ngày với ngân sách 1590 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí thuật ngữ thống nhất, ví dụ kiểm chứng được và mục lục tra cứu rõ ràng.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (23400, 22200, 21008, 1560, 'Chào Ngô Thanh Quân, tôi là Nguyễn Thiên Uyên, chuyên viên tài liệu kỹ thuật. Với yêu cầu biên tập tài liệu quản trị hệ thống, tôi sẽ dùng tài liệu Markdown, sơ đồ quy trình và kiểm chứng ví dụ API và chia việc thành ba mốc: Khảo sát sản phẩm và xây dựng đề cương; Biên soạn nội dung và ví dụ sử dụng; Rà soát thuật ngữ và bàn giao tài liệu. Tôi đề xuất 65 ngày với ngân sách 1560 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí thuật ngữ thống nhất, ví dụ kiểm chứng được và mục lục tra cứu rõ ràng.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY));
    INSERT INTO proposals (proposal_id, job_id, freelancer_id, proposed_amount, cover_letter, estimated_days, submitted_at) VALUES
        (23401, 22201, 21001, 2670, 'Chào Hoàng Xuân Dũng, tôi là Cao Bảo Giang, lập trình viên web full stack. Với yêu cầu xây dựng cổng đặt hàng, tôi sẽ dùng React, TypeScript và Node.js và chia việc thành ba mốc: Thiết kế luồng mua hàng và giao diện mẫu; Lập trình danh mục, giỏ hàng và quản lý đơn; Kiểm thử thanh toán và bàn giao website. Tôi đề xuất 60 ngày với ngân sách 2670 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí giao diện responsive, phân quyền quản trị và kiểm thử luồng đặt hàng.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (23402, 22201, 21009, 2640, 'Chào Hoàng Xuân Dũng, tôi là Bùi Minh Hân, lập trình viên web full stack. Với yêu cầu xây dựng cổng đặt hàng, tôi sẽ dùng React, TypeScript và Node.js và chia việc thành ba mốc: Thiết kế luồng mua hàng và giao diện mẫu; Lập trình danh mục, giỏ hàng và quản lý đơn; Kiểm thử thanh toán và bàn giao website. Tôi đề xuất 65 ngày với ngân sách 2640 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí giao diện responsive, phân quyền quản trị và kiểm thử luồng đặt hàng.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY)),
        (23403, 22202, 21002, 3270, 'Chào Mai Minh Hân, tôi là Đinh Gia Bình, lập trình viên ứng dụng di động. Với yêu cầu phát triển ứng dụng đặt lịch, tôi sẽ dùng React Native, TypeScript và REST API và chia việc thành ba mốc: Đặc tả màn hình và thiết kế luồng sử dụng; Lập trình ứng dụng và kết nối API; Kiểm thử thiết bị và bàn giao bản cài. Tôi đề xuất 60 ngày với ngân sách 3270 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí đăng nhập, thông báo trạng thái, kiểm thử trên Android và iOS.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (23404, 22202, 21010, 3240, 'Chào Mai Minh Hân, tôi là Tạ Thùy An, lập trình viên ứng dụng di động. Với yêu cầu phát triển ứng dụng đặt lịch, tôi sẽ dùng React Native, TypeScript và REST API và chia việc thành ba mốc: Đặc tả màn hình và thiết kế luồng sử dụng; Lập trình ứng dụng và kết nối API; Kiểm thử thiết bị và bàn giao bản cài. Tôi đề xuất 65 ngày với ngân sách 3240 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí đăng nhập, thông báo trạng thái, kiểm thử trên Android và iOS.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY)),
        (23405, 22203, 21003, 2970, 'Chào Bùi Tuấn Nam, tôi là Hoàng Xuân Trí, kỹ sư dữ liệu. Với yêu cầu xây dựng pipeline đồng bộ dữ liệu, tôi sẽ dùng Python, SQL và Docker và chia việc thành ba mốc: Khảo sát nguồn và thiết kế mô hình dữ liệu; Xây dựng pipeline ETL và kiểm tra chất lượng; Chạy đối soát và bàn giao lịch đồng bộ. Tôi đề xuất 60 ngày với ngân sách 2970 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí chống bản ghi trùng, ghi log lỗi và đối soát tổng số bản ghi.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (23406, 22203, 21011, 2940, 'Chào Bùi Tuấn Nam, tôi là Hoàng Đức Hân, kỹ sư dữ liệu. Với yêu cầu xây dựng pipeline đồng bộ dữ liệu, tôi sẽ dùng Python, SQL và Docker và chia việc thành ba mốc: Khảo sát nguồn và thiết kế mô hình dữ liệu; Xây dựng pipeline ETL và kiểm tra chất lượng; Chạy đối soát và bàn giao lịch đồng bộ. Tôi đề xuất 65 ngày với ngân sách 2940 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí chống bản ghi trùng, ghi log lỗi và đối soát tổng số bản ghi.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY)),
        (23407, 22204, 21004, 2370, 'Chào Võ Ngọc Vy, tôi là Mai Thiên Trúc, chuyên viên phân tích dữ liệu. Với yêu cầu thiết kế dashboard doanh thu, tôi sẽ dùng SQL, Power BI và mô hình dữ liệu dạng sao và chia việc thành ba mốc: Thống nhất chỉ số và chuẩn hóa nguồn dữ liệu; Thiết kế dashboard và bộ lọc phân tích; Đối soát số liệu và hướng dẫn sử dụng. Tôi đề xuất 60 ngày với ngân sách 2370 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí chỉ số có công thức rõ ràng, bộ lọc theo kỳ và số liệu khớp nguồn.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
