        (24200, 22600, 21008, 1740, 'Chào Ngô Thanh Quân, tôi là Nguyễn Thiên Uyên, chuyên viên tài liệu kỹ thuật. Với yêu cầu biên tập tài liệu quản trị hệ thống, tôi sẽ dùng tài liệu Markdown, sơ đồ quy trình và kiểm chứng ví dụ API và chia việc thành ba mốc: Khảo sát sản phẩm và xây dựng đề cương; Biên soạn nội dung và ví dụ sử dụng; Rà soát thuật ngữ và bàn giao tài liệu. Tôi đề xuất 65 ngày với ngân sách 1740 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí thuật ngữ thống nhất, ví dụ kiểm chứng được và mục lục tra cứu rõ ràng.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY));
    INSERT INTO proposals (proposal_id, job_id, freelancer_id, proposed_amount, cover_letter, estimated_days, submitted_at) VALUES
        (24201, 22601, 21001, 2850, 'Chào Hoàng Xuân Dũng, tôi là Cao Bảo Giang, lập trình viên web full stack. Với yêu cầu xây dựng cổng đặt hàng, tôi sẽ dùng React, TypeScript và Node.js và chia việc thành ba mốc: Thiết kế luồng mua hàng và giao diện mẫu; Lập trình danh mục, giỏ hàng và quản lý đơn; Kiểm thử thanh toán và bàn giao website. Tôi đề xuất 60 ngày với ngân sách 2850 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí giao diện responsive, phân quyền quản trị và kiểm thử luồng đặt hàng.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (24202, 22601, 21009, 2820, 'Chào Hoàng Xuân Dũng, tôi là Bùi Minh Hân, lập trình viên web full stack. Với yêu cầu xây dựng cổng đặt hàng, tôi sẽ dùng React, TypeScript và Node.js và chia việc thành ba mốc: Thiết kế luồng mua hàng và giao diện mẫu; Lập trình danh mục, giỏ hàng và quản lý đơn; Kiểm thử thanh toán và bàn giao website. Tôi đề xuất 65 ngày với ngân sách 2820 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí giao diện responsive, phân quyền quản trị và kiểm thử luồng đặt hàng.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY)),
        (24203, 22602, 21002, 3450, 'Chào Mai Minh Hân, tôi là Đinh Gia Bình, lập trình viên ứng dụng di động. Với yêu cầu phát triển ứng dụng đặt lịch, tôi sẽ dùng React Native, TypeScript và REST API và chia việc thành ba mốc: Đặc tả màn hình và thiết kế luồng sử dụng; Lập trình ứng dụng và kết nối API; Kiểm thử thiết bị và bàn giao bản cài. Tôi đề xuất 60 ngày với ngân sách 3450 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí đăng nhập, thông báo trạng thái, kiểm thử trên Android và iOS.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (24204, 22602, 21010, 3420, 'Chào Mai Minh Hân, tôi là Tạ Thùy An, lập trình viên ứng dụng di động. Với yêu cầu phát triển ứng dụng đặt lịch, tôi sẽ dùng React Native, TypeScript và REST API và chia việc thành ba mốc: Đặc tả màn hình và thiết kế luồng sử dụng; Lập trình ứng dụng và kết nối API; Kiểm thử thiết bị và bàn giao bản cài. Tôi đề xuất 65 ngày với ngân sách 3420 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí đăng nhập, thông báo trạng thái, kiểm thử trên Android và iOS.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY)),
        (24205, 22603, 21003, 3150, 'Chào Bùi Tuấn Nam, tôi là Hoàng Xuân Trí, kỹ sư dữ liệu. Với yêu cầu xây dựng pipeline đồng bộ dữ liệu, tôi sẽ dùng Python, SQL và Docker và chia việc thành ba mốc: Khảo sát nguồn và thiết kế mô hình dữ liệu; Xây dựng pipeline ETL và kiểm tra chất lượng; Chạy đối soát và bàn giao lịch đồng bộ. Tôi đề xuất 60 ngày với ngân sách 3150 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí chống bản ghi trùng, ghi log lỗi và đối soát tổng số bản ghi.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
        (24206, 22603, 21011, 3120, 'Chào Bùi Tuấn Nam, tôi là Hoàng Đức Hân, kỹ sư dữ liệu. Với yêu cầu xây dựng pipeline đồng bộ dữ liệu, tôi sẽ dùng Python, SQL và Docker và chia việc thành ba mốc: Khảo sát nguồn và thiết kế mô hình dữ liệu; Xây dựng pipeline ETL và kiểm tra chất lượng; Chạy đối soát và bàn giao lịch đồng bộ. Tôi đề xuất 65 ngày với ngân sách 3120 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí chống bản ghi trùng, ghi log lỗi và đối soát tổng số bản ghi.', 65, DATE_SUB(CURRENT_DATE, INTERVAL 9 DAY)),
        (24207, 22604, 21004, 2550, 'Chào Võ Ngọc Vy, tôi là Mai Thiên Trúc, chuyên viên phân tích dữ liệu. Với yêu cầu thiết kế dashboard doanh thu, tôi sẽ dùng SQL, Power BI và mô hình dữ liệu dạng sao và chia việc thành ba mốc: Thống nhất chỉ số và chuẩn hóa nguồn dữ liệu; Thiết kế dashboard và bộ lọc phân tích; Đối soát số liệu và hướng dẫn sử dụng. Tôi đề xuất 60 ngày với ngân sách 2550 USD, gửi cập nhật mỗi tuần và bàn giao sau khi đối chiếu tiêu chí chỉ số có công thức rõ ràng, bộ lọc theo kỳ và số liệu khớp nguồn.', 60, DATE_SUB(CURRENT_DATE, INTERVAL 10 DAY)),
